"""Заключение ЭПБ из готового ТО: значения и расчёты только из входного документа.

Публичные даты — ISO YYYY-MM-DD. Пагинацию и копии приложений выполняет
expertise_render; ручной report_pages имеет приоритет над числом страниц PDF.
Неподтверждённое положительное заключение (дефекты, отсутствующие расчёты,
неработоспособное состояние) не выпускается. Вызов — только в рабочем потоке.
"""
from __future__ import annotations

from copy import deepcopy
from datetime import date
from io import BytesIO
import os
from pathlib import Path
import re
from zipfile import ZipFile

from docx import Document
from docx.oxml import OxmlElement, parse_xml
from docx.oxml.ns import qn
from docx.opc.packuri import PackURI
from docx.opc.part import Part
from docx.shared import Inches
from docx.table import Table

from .docx_cells import iter_rows_cells, row_cells
from .expertise_catalog import get_opo, get_order, load_catalog

_TEMPLATE = Path(__file__).resolve().parents[1] / 'templates' / 'expertise' / 'conclusion.docx'
_REL_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
_MONTHS = ('января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля',
           'августа', 'сентября', 'октября', 'ноября', 'декабря')


def has_access(user_id) -> bool:
    """Пустой whitelist не открывает доступ никому, включая администратора."""
    if isinstance(user_id, (bool, float)):
        return False
    try:
        value = int(user_id)
    except (TypeError, ValueError):
        return False
    return value > 0 and str(value) in {
        item.strip() for item in os.getenv('EXPERTISE_USER_IDS', '').split(',')
    }


def metadata() -> dict:
    catalog = load_catalog()
    return {key: [{'id': item['id'], 'label': item['label']} for item in catalog[key]]
            for key in ('opos', 'orders')}


def _text(element) -> str:
    """Текст элемента: runs внутри абзаца склеиваются БЕЗ разделителя (Word режет
    слова и числа на произвольные runs), абзацы между собой разделяются пробелом."""
    parts = []
    last = None
    run_tag = qn('w:r')
    for node in element.iter(qn('w:t'), qn('w:tab'), qn('w:br'), qn('w:cr'), qn('w:noBreakHyphen')):
        if node.tag != qn('w:t') and node.getparent().tag != run_tag:
            continue  # w:tab внутри w:tabs - это описание табуляции, а не символ
        paragraph = next(node.iterancestors(qn('w:p')), None)
        if parts and paragraph is not last:
            parts.append(' ')
        last = paragraph
        if node.tag == qn('w:t'):
            parts.append(node.text or '')
        elif node.tag == qn('w:noBreakHyphen'):
            parts.append('-')
        else:
            parts.append(' ')
    return ''.join(parts).strip()


def _norm(value: str) -> str:
    return re.sub(r'\s+', '', value).casefold().replace('ё', 'е')


def _date(value: str, field: str) -> date:
    if not isinstance(value, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        raise ValueError(f'{field}: укажите дату в формате ГГГГ-ММ-ДД.')
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f'{field}: некорректная дата.') from exc
def _document_date(year, month, day):
    try:
        return date(int(year), int(month), int(day))
    except ValueError as exc:
        raise ValueError('ТО содержит некорректную календарную дату.') from exc




def _russian_date(value: date) -> str:
    return f'{value.day} {_MONTHS[value.month - 1]} {value.year} года'


def _read_docx(data: bytes, label: str):
    try:
        with ZipFile(BytesIO(data)) as archive:
            if 'word/document.xml' not in archive.namelist():
                raise ValueError(f'{label}: требуется документ DOCX.')
            if any(name.endswith('vbaProject.bin') for name in archive.namelist()):
                raise ValueError(f'{label}: документ с макросами не поддерживается.')
        doc = Document(BytesIO(data))
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc).startswith(label + ':'):
            raise
        raise ValueError(f'{label}: не удалось прочитать DOCX.') from exc
    # Внешние изображения и вложенные документы не должны загружаться Word при открытии.
    for part in doc.part.package.parts:
        for rel in part.rels.values():
            if rel.is_external and not rel.reltype.endswith('/hyperlink'):
                raise ValueError(f'{label}: внешние связи документа не поддерживаются.')
    return doc


def _flatten_controls(element):
    """Снимает dataBinding, способный вернуть реквизиты образца при открытии Word."""
    for control in reversed(list(element.iter(qn('w:sdt')))):
        parent = control.getparent()
        content = control.find(qn('w:sdtContent'))
        if parent is not None and content is not None:
            for child in list(content):
                control.addprevious(child)
            parent.remove(control)


class _Source:
    def __init__(self, doc):
        self.doc = doc
        for table in doc.element.body.iter(qn('w:tbl')):
            _flatten_controls(table)
        self.blocks = list(doc.element.body)
        self.strings = [_text(e) for e in self.blocks]
        self.keys = [_norm(s) for s in self.strings]
        self.appendices = {}
        for i, key in enumerate(self.keys):
            match = re.match(r'^приложение(\d+)\.', key)
            if match and 'продолжение' not in key:
                self.appendices.setdefault(int(match[1]), i)

    def find(self, fragment: str, start=0, end=None) -> int:
        key = _norm(fragment)
        hits = [i for i in range(start, len(self.blocks) if end is None else end)
                if key in self.keys[i] and self.blocks[i].tag == qn('w:p')]
        if not hits:
            raise ValueError(f'Неподдерживаемый ТО: не найден раздел «{fragment}».')
        return hits[0]

    def appendix(self, number: int) -> tuple[int, int]:
        if number not in self.appendices:
            raise ValueError(f'В ТО отсутствует приложение {number}.')
        start = self.appendices[number]
        end = min((i for n, i in self.appendices.items() if i > start),
                  default=len(self.blocks) - 1)
        return start, end

    def section(self, start: str, end: str, bounds=None):
        low, high = bounds or (0, self.appendix(1)[0])
        first = self.find(start, low, high)
        last = self.find(end, first + 1, high)
        return self.blocks[first + 1:last]

    def table(self, fragment: str, bounds=None):
        low, high = bounds or (0, len(self.blocks))
        key = _norm(fragment)
        hits = [e for e in self.blocks[low:high]
                if e.tag == qn('w:tbl') and key in _norm(_text(e))]
        if not hits:
            raise ValueError(f'Неподдерживаемый ТО: не найдена таблица «{fragment}».')
        if len(hits) > 1:
            raise ValueError(f'Неподдерживаемый ТО: неоднозначная таблица «{fragment}».')
        return hits[0]


def _rows(element, doc):
    return list(iter_rows_cells(Table(element, doc._body)))


