PRESSURE_OPTIONS = {"ВВД": ["16,0", "21,0"]}
PRESSURE_FAR = 3.0   # паспортное давление дальше этого от выбранного (МПа): выбор сомнителен, подсвечивается
TEMPERATURE = "15"
ANTI_CORROSION_DEFAULT = "Лакокрасочное покрытие, лента ПВХ"  # «в 99% случаев»


PURPOSE_ABBREVIATIONS = {"вл": "ВЛ", "нс": "НС", "нн": "НН", "ввд": "ВВД", "внд": "ВНД", "гп": "ГП"}


def purpose_code(text: str | None) -> str | None:
    """Назначение из паспорта -> код (ВЛ/НС/ВВД/ВНД/ГП/НН) по ключевым словам."""
    t = (text or "").lower().replace("ё", "е")
    if "выкидн" in t:
        return "ВЛ"
    if "нефтесбор" in t or "нефтегазосбор" in t:
        return "НС"
    if "напорн" in t and "нефтепровод" in t:
        return "НН"
    if "водовод" in t:
        if "высок" in t:
            return "ВВД"
        if "низк" in t:
            return "ВНД"
    if "газопровод" in t:
        return "ГП"
    return PURPOSE_ABBREVIATIONS.get(t.strip(" .,;:"))   # в шапке назначение бывает записано сокращением («ВВД»)


def choose_pressure(code: str | None, raw_value: str | None) -> tuple[str | None, bool, str | None, list[str]]:
    """Давление формы: (значение, нужна проверка, пояснение, кандидаты для подбора S мин).

    У ВВД из паспорта берётся ближайшее допустимое к верхней границе рабочего давления («13-15» -> 16,0); не прочитано -
    16,0 по умолчанию, а S мин подбирается так, чтобы подошли оба варианта. У остальных назначений давление одно."""
    default = RULES.get(code, (None, None, None))[2]
    if default is None:
        return None, True, "правила для типа нет в ТЗ", []
    options = PRESSURE_OPTIONS.get(code)
    if not options:
        return default, False, "по типу трубопровода", [default]
    numbers = [float(x.replace(",", ".")) for x in re.findall(r"\d+(?:[.,]\d+)?", raw_value or "")]
    if not numbers:
        return default, True, f"давление в паспорте не прочитано: взято {default} (чаще всего), возможно {' или '.join(options)}", list(options)
    top = max(numbers)
    value = lambda option: float(option.replace(",", "."))
    nearest = min(options, key=lambda option: (abs(value(option) - top), -value(option)))
    return nearest, abs(value(nearest) - top) > PRESSURE_FAR, f"в паспорте {raw_value.strip()} МПа: выбрано ближайшее допустимое", [nearest]

