def _pipe_columns(element, doc):
    rows = _rows(element, doc)
    first = rows[0]
    result, seen = [], set()
    for index, cell in enumerate(first):
        if not index or not _norm(cell.text).startswith('труба'):
            continue
        # gridSpan может занимать несколько логических колонок одной трубы.
        # Две реальные трубы (даже одинакового диаметра) имеют разные ячейки.
        signature = tuple(row[index]._tc for row in rows if len(row) == len(first))
        if signature not in seen:
            result.append(index)
            seen.add(signature)
    if not result:
        raise ValueError('Неподдерживаемый ТО: в расчёте не найдены колонки труб.')
    return [0, *result]


def _section_text(blocks):
    return '\n'.join(_text(e) for e in blocks if _text(e))


def _required(value: str, label: str):
    if not value or not value.strip(' -–—.'):
        raise ValueError(f'В ТО отсутствуют критичные данные: {label}.')
    return value.strip()


def _extract(source: _Source):
    app1 = source.appendix(1)
    main = source.table('Назначение трубопровода', app1)
    rows = _rows(main, source.doc)
    data = {_norm(row[0].text): [cell.text.strip() for cell in row[1:]] for row in rows}

    def field(fragment):
        key = _norm(fragment)
        values = [data[key]] if key in data else [v for k, v in data.items() if key in k]
        if len(values) != 1:
            raise ValueError(f'Неподдерживаемый ТО: не найдено поле «{fragment}».')
        for value in values[0]:
            _required(value, fragment)
        return ', '.join(dict.fromkeys(values[0]))

    title_end = source.find('Общие сведения')
    title = source.strings[:title_end]
    number_line = next((s for s in title if 'ТЕХНИЧЕСКИЙ' in s.upper() and 'ОТЧЕТ' in s.upper().replace('Ё', 'Е')), '')
    number_match = re.search(r'№\s*(.+)', number_line)
    if not number_match:
        raise ValueError('В ТО не найден номер технического отчета на титульном листе.')
    report_number = re.sub(r'\s+', '', number_match[1]).replace('–', '-').replace('—', '-')
    if not re.fullmatch(r'ТО-[А-ЯA-Z0-9/-]+', report_number, re.I):
        raise ValueError('Неподдерживаемый номер ТО на титульном листе.')
    inventory_line = next((s for s in title if re.search(r'инв\s*\.', s, re.I)), '')
    inv = re.search(r'№\s*([\w./-]+)', inventory_line)
    if not inv:
        raise ValueError('В ТО не найден инвентарный номер на титульном листе.')
    inv_index = title.index(inventory_line)
    following = [s for s in title[inv_index + 1:] if s.strip()]
    if len(following) < 3 or 'месторождение' not in following[0].casefold():
        raise ValueError('В ТО не найдены месторождение, регион и заказчик на титульном листе.')
    if not all(name in _norm(following[2]) for name in ('башнефть', 'добыча')):
        raise ValueError('Автоматическое заключение поддерживает только ТО заказчика ООО «Башнефть – Добыча».')
    approval = '\n'.join(title[:title.index(number_line)])
    date_match = re.search(r'[«\"]?\s*(\d{1,2})\s*[»\"]?\s*(' + '|'.join(_MONTHS) + r')\s*(\d{4})', approval, re.I)
    if date_match:
        report_date = _document_date(date_match[3], _MONTHS.index(date_match[2].casefold()) + 1, date_match[1])
    else:
        numeric = re.search(r'(\d{1,2})\s*\.\s*(\d{1,2})\s*\.\s*(\d{4})', approval)
        if not numeric:
            raise ValueError('В ТО не найдена дата утверждения на титульном листе.')
        report_date = _document_date(numeric[3], numeric[2], numeric[1])
    diagnosis = next((s for s in source.strings if 'техническоедиагностированиевыполнено' in _norm(s)), '')
    diagnosis_match = re.search(r'(\d{1,2})\s*\.\s*(\d{1,2})\s*\.\s*(\d{4})', diagnosis)
    if not diagnosis_match:
        raise ValueError('В ТО не найдена дата технического диагностирования.')
    diagnosis_date = _document_date(diagnosis_match[3], diagnosis_match[2], diagnosis_match[1])
    history = _section_text(source.section('Сведения о ранее проведенных', 'Сведения об отказах', app1))
    failures = _section_text(source.section('Сведения об отказах', 'Сведения об испытаниях', app1))
    trials = _section_text(source.section('Сведения об испытаниях', 'Сведения о технических обслуживаниях', app1))
    repairs = _section_text(source.section('Сведения о технических обслуживаниях', 'Сведения о фланцах', app1))
    for label, value in (('предыдущие экспертизы', history), ('отказы', failures), ('испытания', trials), ('ремонты', repairs)):
        _required(value, label)
    analysis = source.section('Результаты анализа технической документации', 'Состояние трассы трубопровода')
    completeness = next((_text(e) for e in analysis if 'комплектность' in _text(e).casefold()), '')
    compliance = next((_text(e) for e in analysis if 'технические характеристики' in _text(e).casefold()), '')
    condition = _section_text(source.section('Оценка технического состояния', 'Рекомендации'))
    if ('признаноработоспособным' not in _norm(condition)
            or 'непризнаноработоспособным' in _norm(condition)):
        raise ValueError('ТО не подтверждает работоспособность. Автоматическое положительное заключение не поддерживается.')
    recommendation_start = source.find('Рекомендации')
    recommendation_end = source.find('Ведомость дефектов', recommendation_start + 1)
    recommendations = _section_text(source.blocks[recommendation_start + 1:recommendation_end])
    recommendations = re.sub(r'\s+', ' ', recommendations)  # включая неразрывные пробелы
    safe = re.search(r'не\s*позднее\s*[«\"]?\s*(\d{1,2})\s*[»\"]?\s*(' + '|'.join(_MONTHS) + r')\s*(\d{4})', recommendations, re.I)
    if safe:
        safe_date = _document_date(safe[3], _MONTHS.index(safe[2].casefold()) + 1, safe[1])
    else:
        safe_numeric = re.search(r'не\s*позднее\s*(\d{1,2})\s*\.\s*(\d{1,2})\s*\.\s*(\d{4})', recommendations, re.I)
…
