"""Форматирование реквизитов заключения промышленной безопасности."""
from datetime import date
import re


_FORMS = {
    'ВЛ': ('выкидная линия', 'выкидной линии', 'предназначена'),
    'НС': ('нефтегазосборный трубопровод', 'нефтегазосборного трубопровода', 'предназначен'),
    'НН': ('напорный нефтепровод', 'напорного нефтепровода', 'предназначен'),
    'ВВД': ('водовод высокого давления', 'водовода высокого давления', 'предназначен'),
    'ВНД': ('водовод низкого давления', 'водовода низкого давления', 'предназначен'),
    'ГП': ('газопровод', 'газопровода', 'предназначен'),
}
_EXPERTS = {
    'Султаншин И. Х.': 'Султаншиным И. Х.',
    'Тяжельников Е. В.': 'Тяжельниковым Е. В.',
    'Сорокина Т. И.': 'Сорокиной Т. И.',
    'Гареева Р. Р.': 'Гареевой Р. Р.',
    'Гвоздецкая В. А.': 'Гвоздецкой В. А.',
    'Юлуев Т. К.': 'Юлуевым Т. К.',
}
_MONTHS = ('января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля',
           'августа', 'сентября', 'октября', 'ноября', 'декабря')


def _clean_text(value: str) -> str:
    value = re.sub(r'\s+', ' ', value).strip()
    value = re.sub(r'\s+([,.;:)»])', r'\1', value)
    return re.sub(r'([«(])\s+', r'\1', value)


def _object_forms(purpose: str, object_name: str) -> dict[str, str]:
    purpose, title = _clean_text(purpose), _clean_text(object_name)
    code = purpose.upper()
    if code not in _FORMS:
        code = next((key for key, (nom, _, _) in _FORMS.items()
                     if purpose.casefold() == nom.casefold()), '')
    if not code:
        raise ValueError('Неподдерживаемое назначение трубопровода для склонения.')
    nom, gen, verb = _FORMS[code]
    if not title.casefold().startswith(nom.casefold()):
        raise ValueError('Неподдерживаемое назначение трубопровода для склонения.')
    rest = title[len(nom):]
    if rest and not rest[0].isspace() and rest[0] != '«':
        raise ValueError('Неподдерживаемое назначение трубопровода для склонения.')
    return dict(title=title, nom=nom + rest, gen=gen + rest,
                purpose_nom=nom, purpose_gen=gen, destination_verb=verb)


def _full_object(values: dict, object_name: str, *, commas: bool = False) -> str:
    parts = (object_name, 'инв. № ' + values['inventory'], values['field'],
             values['region'], values['customer'])
    return (', ' if commas else ' ').join(_clean_text(part) for part in parts)


def _expert_instrumental(name: str) -> str:
    name = _clean_text(name)
    try:
        return _EXPERTS[name]
    except KeyError as exc:
        raise ValueError(f'Неизвестный эксперт для склонения: {name}.') from exc


def _title_date(value: date) -> str:
