            span = tcpr.find(qn('w:gridSpan')) if tcpr is not None else None
            count = int(span.get(qn('w:val'))) if span is not None else 1
            if index < 0 or count <= 0 or index + count > len(widths_twips):
                raise ValueError('Ячейка таблицы выходит за границы сетки.')
            cells.append((cell, sum(widths_twips[index:index + count])))
            index += count
        rows.append(cells)
    tblpr = table_element.find(qn('w:tblPr'))
    if tblpr is None:
        tblpr = OxmlElement('w:tblPr')
        table_element.insert(0, tblpr)
    for name, attrs in (('tblW', {'w': str(sum(widths_twips)), 'type': 'dxa'}),
                        ('tblLayout', {'type': 'fixed'})):
        node = tblpr.find(qn('w:' + name))
        if node is None:
            node = OxmlElement('w:' + name)
            tblpr.append(node)
        for key, value in attrs.items():
            node.set(qn('w:' + key), value)
    grid = table_element.find(qn('w:tblGrid'))
    if grid is None:
        grid = OxmlElement('w:tblGrid')
        tblpr.addnext(grid)
    for child in list(grid):
        grid.remove(child)
    for width in widths_twips:
        col = OxmlElement('w:gridCol')
        col.set(qn('w:w'), str(width))
        grid.append(col)
    for cells in rows:
        for cell, width in cells:
            props = cell.find(qn('w:tcPr'))
            if props is None:
                props = OxmlElement('w:tcPr')
                cell.insert(0, props)
            node = props.find(qn('w:tcW'))
            if node is None:
                node = OxmlElement('w:tcW')
                props.insert(0, node)
            node.set(qn('w:w'), str(width))
            node.set(qn('w:type'), 'dxa')

