class _Importer:
    """Импорт OOXML с собственными стилями, numbering и графом отношений.

    Не переносит разделы/колонтитулы ТО: таблицы становятся частью заключения,
    а растровые приложения сохраняют реальную верстку исходного PDF.
    """
    def __init__(self, source, target):
        self.source, self.target = source, target
        self.package = target.part.package
        self.parts = {}
        self.occupied = {str(p.partname) for p in self.package.parts}
        self.style_map = {}
        self.num_map = {}
        self._merge_definitions()

    def _merge_definitions(self):
        src_styles = self.source.styles.element
        dst_styles = self.target.styles.element
        prefix = 'EPB_TO_'
        used = {e.get(qn('w:styleId')) for e in dst_styles}
        while any(prefix + e.get(qn('w:styleId'), '') in used for e in src_styles):
            prefix += 'X_'
        for style in src_styles:
            sid = style.get(qn('w:styleId'))
            if sid:
                self.style_map[sid] = prefix + sid
        src_num = self.source.part.numbering_part.element
        dst_num = self.target.part.numbering_part.element
        abstract_map = {}
        for kind, attr, mapping in (('abstractNum', 'abstractNumId', abstract_map),
                                    ('num', 'numId', self.num_map)):
            existing = [int(e.get(qn('w:' + attr))) for e in dst_num.findall(qn('w:' + kind))]
            next_id = max(existing, default=0) + 1
            for e in src_num.findall(qn('w:' + kind)):
                old = e.get(qn('w:' + attr))
                mapping[old] = str(next_id)
                next_id += 1
            for e in src_num.findall(qn('w:' + kind)):
                clone = deepcopy(e)
                clone.set(qn('w:' + attr), mapping[e.get(qn('w:' + attr))])
                for ref in clone.iter(qn('w:abstractNumId')):
                    ref.set(qn('w:val'), abstract_map[ref.get(qn('w:val'))])
                self._rewrite_definitions(clone)
                # abstractNum precedes num in the OOXML schema.
                if kind == 'abstractNum':
                    nums = dst_num.findall(qn('w:num'))
                    if nums:
                        nums[0].addprevious(clone)
                    else:
                        dst_num.append(clone)
                else:
                    dst_num.append(clone)
        for style in src_styles:
            sid = style.get(qn('w:styleId'))
            if not sid:
                continue
            clone = deepcopy(style)
            clone.set(qn('w:styleId'), self.style_map[sid])
            clone.attrib.pop(qn('w:default'), None)
            self._rewrite_definitions(clone)
            dst_styles.append(clone)

    def _rewrite_definitions(self, element):
        for node in element.iter():
            if node.tag in {qn('w:pStyle'), qn('w:rStyle'), qn('w:tblStyle'),
                            qn('w:basedOn'), qn('w:next'), qn('w:link'),
                            qn('w:styleLink'), qn('w:numStyleLink')}:
                value = node.get(qn('w:val'))
                if value in self.style_map:
                    node.set(qn('w:val'), self.style_map[value])
            elif node.tag == qn('w:numId'):
                value = node.get(qn('w:val'))
                if value in self.num_map:
                    node.set(qn('w:val'), self.num_map[value])

    def _part(self, source):
        if source in self.parts:
            return self.parts[source]
        old = Path(str(source.partname))
        index = 1
        name = f'{old.parent.as_posix()}/epb_{index}_{old.name}'
        while name in self.occupied:
            index += 1
            name = f'{old.parent.as_posix()}/epb_{index}_{old.name}'
        self.occupied.add(name)
        target = Part(PackURI(name), source.content_type, source.blob, self.package)
        self.parts[source] = target
        # В дочерних XML сохраняются исходные rId — меняются только адреса частей.
        for rid, rel in source.rels.items():
            destination = rel.target_ref if rel.is_external else self._part(rel.target_part)
            target.rels.add_relationship(rel.reltype, destination, rid, rel.is_external)
        return target

    def copy(self, element):
        clone = deepcopy(element)
        self._rewrite_definitions(clone)
        for node in list(clone.iter()):
            if node.tag in {qn('w:sectPr'), qn('w:bookmarkStart'), qn('w:bookmarkEnd'),
                            qn('w:commentRangeStart'), qn('w:commentRangeEnd'),
                            qn('w:commentReference')}:
                if node.getparent() is not None:
                    node.getparent().remove(node)
                continue
            for attr, value in list(node.attrib.items()):
                if attr.startswith('{' + _REL_NS + '}'):
                    if value not in self.source.part.rels:
                        raise ValueError('ТО содержит поврежденную связь рисунка или таблицы.')
                    rel = self.source.part.rels[value]
                    destination = rel.target_ref if rel.is_external else self._part(rel.target_part)
                    node.set(attr, self.target.part.relate_to(destination, rel.reltype, rel.is_external))
        return clone


def _plain_table(doc, headers, rows):
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = 'Table Grid'
    for cell, value in zip(next(iter_rows_cells(table)), headers):
