    """Собирает DOCX; ValueError — понятный пользователю отказ без результата."""
…
    try:
        rendered = render_attachments(source, require_act=act is None)
        act_images = render_act(act) if act is not None else rendered['act']
    except RuntimeError as exc:
        raise ValueError(str(exc)) from exc
    pages = report_pages if report_pages is not None else rendered['pages']
    if not isinstance(pages, int) or pages <= 0 or not act_images or not rendered['protocols']:
        raise ValueError('Не удалось получить страницы ТО, акт и протоколы диагностирования.')
    report_row = _plain_table(doc, ['Шифр', 'Документ', 'Дата', 'Листов'], [[values['report_number'],
