    for row in _rows(analysis_table, doc):
        if _norm(row[0].text) == 'в)':
            row[-1].text = ('отсутствуют (аварии не зарегистрированы)' if 'незафиксированы' in _norm(values['failures'])
                            else 'имеются, не предоставлены для рассмотрения в рамках проведения ЭПБ')
