                            else 'имеются, рассмотрены в рамках проведения ЭПБ')
    results_rows = []
    source_main_end = parsed.appendix(1)[0]
    primary = parsed.blocks[parsed.find('Состояние трассы трубопровода'):source_main_end]
    primary_paragraphs = [_text(e) for e in primary if e.tag == qn('w:p') and _text(e)]
    for value in primary_paragraphs:
        key = _norm(value)
        if any(term in key for term in ('неудовлетвор', 'негоден', 'дефектыобнаружены', 'обнаруженыдефекты')):
            raise ValueError('ТО содержит отрицательные результаты контроля: требуется ручная экспертиза.')
    for fragment, title in (('Состояние охранной зоны трассы', 'Обследование охранной зоны трубопровода'),
                            ('Глубина заложения трубопровода соответствует', 'Определение глубины залегания трубопровода')):
        statements = [source_text(t) for t in primary_paragraphs if _norm(fragment) in _norm(t)]
        if not statements:
            raise ValueError(f'В ТО отсутствует итог контроля: {title}.')
        results_rows.append([str(len(results_rows) + 1), title, '\n'.join(statements), 'По данным ТО'])
    # Приложения 7/8 часто целиком растровые: текстовый итог есть в основной части ТО.
    for number, title in ((5, 'Коррозионная агрессивность грунтов'), (6, 'Блуждающие токи'),
                           (7, 'Состояние защитного покрытия'), (8, 'Адгезия защитного покрытия'),
                           (9, 'Потенциал «труба–земля»'), (10, 'Визуальный и измерительный контроль'),
                           (11, 'Ультразвуковой контроль сварных соединений'), (12, 'Ультразвуковая толщинометрия'),
                           (13, 'Твердость металла'), (14, 'Переходы через препятствия')):
        low, high = parsed.appendix(number)
        statements = []
        for e in parsed.blocks[low:high]:
            if e.tag != qn('w:p'):
                continue
            t = _text(e)
            key = _norm(t)
            if any(word in key for word in ('вывод:', 'состояние', 'величинаостаточной', 'значениятвердости',
                                            'необнаружен', 'соответствуют', 'соответствует', 'отсутствуют', 'измеренныезначениязащитногопотенциала')):
                if t and not re.match(r'^(приложение|протокол)', key):
                    statements.append(source_text(t))
        if not statements and number in (7, 8):
            fragments = (('состояниеизоляционногопокрытия', 'состояниезащитногопокрытия') if number == 7
                         else ('состояниеадгезиипорезультатам',))
            statements = [source_text(t) for t in primary_paragraphs
                          if any(f in _norm(t) for f in fragments)
                          and any(f in _norm(t) for f in ('удовлетвор', 'соответств', 'неудовлетвор'))]
        if not statements:
            if number == 14 and any('отсутствуют' in parsed.keys[i] for i in range(low, high)):
                statements = ['Переходы через естественные и искусственные препятствия отсутствуют.']
            else:
                raise ValueError(f'В приложении {number} ТО не найдены итоговые результаты контроля.')
        for statement in statements:
            key = _norm(statement)
            if any(s in key for s in ('неудовлетвор', 'несоответств', 'негоден', 'недопустимыедефектыобнаружены',
                                     'дефектыобнаружены', 'обнаруженыдефекты')):
                raise ValueError('ТО содержит отрицательные результаты контроля: требуется ручная экспертиза.')
        groups = {}
        for statement in statements:
            kind = ('камер пуска/приема ОУ' if 'камер' in _norm(statement) else
                    'арматуры и фланцевых соединений' if 'арматур' in _norm(statement) else '')
            group = title + (' ' + kind if number in (10, 12, 13) and kind else '')
            groups.setdefault(group, []).append(statement)
        for group, texts in groups.items():
            results_rows.append([str(len(results_rows) + 1), group, '\n'.join(texts), 'По данным ТО'])
    results_table = _plain_table(doc, ['№', 'Вид контроля', 'Результат', 'Основание'], results_rows)
    # Неизменная таблица 8.3 уже находится в бинарном шаблоне заказчика.
    signatures = []
    for expert in experts:
        qualifications = '; '.join(f"{a['area']}, категория {a['category']}, № {a['certificate_number']}, до {a['valid_until']}" for a in expert['attestations'])
        signatures.append(['Эксперт в области промышленной безопасности: ' + qualifications, '________________', expert['short_name']])
    signatures.append(['Генеральный директор ООО НПО «ОргНефтеГаз»', '________________', 'Э. А. Хакимов'])
    sign_table = _plain_table(doc, ['Квалификация / должность', 'Подпись', 'Фамилия, инициалы'], signatures)
    blocks = dict(expert_table=[parse_xml(order['table_xml'])], main_data=[main],
                  results_table=[results_table],
                  rejection_inputs=[imported(reject_inputs)], rejection_results=[imported(reject_results)],
                  resource_inputs=[imported(resource_inputs)], resource_results=[imported(resource_results)],
                  minimum_inputs=[imported(minimum_inputs)], minimum_results=[imported(minimum_results)], signatures=[sign_table])
    def images(items):
        result = []
        for index, image in enumerate(items):
            paragraph = doc.add_paragraph()
            paragraph.paragraph_format.page_break_before = index > 0
            picture = paragraph.add_run().add_picture(BytesIO(image), width=Inches(6.1))
            if picture.height > Inches(9):
