import unittest
from types import SimpleNamespace

from app.services.expertise_render import _Section, _appendix_starts, _page_section, _protocol_crop


class ExpertisePageSelectionTests(unittest.TestCase):
    def test_contents_and_continuation_do_not_replace_appendix_start(self):
        pages = [
            "Содержание\nПриложение 5. Протокол грунта ........ 15\nПриложение 6. Токи ........ 16",
            "Приложение 5.\nПротокол грунта\nРезультаты контроля",
            "Приложение 5 (продолжение)\nЗамеры",
            "Приложение 6. Токи\nРезультаты контроля",
        ]
        starts = _appendix_starts(pages, {5: (0, "протоколгрунта"), 6: (0, "токи")})
        self.assertEqual(starts, {5: 1, 6: 3})

    def test_crop_geometry_uses_matching_section_not_first_same_size(self):
        page = SimpleNamespace(get_size=lambda: (595, 842))
        sections = [
            _Section(595, 842, 50, 30, ["первыйпротокол"]),
            _Section(595, 842, 70, 40, ["следующийпротокол"]),
            _Section(842, 595, 20, 20, ["следующийпротокол"]),
        ]
        self.assertEqual(_page_section(page, "Следующий протокол", sections, 0), 1)

    def test_continuation_keeps_previously_identified_section(self):
        page = SimpleNamespace(get_size=lambda: (595, 842))
        sections = [_Section(595, 842, 50, 30), _Section(595, 842, 70, 40)]
        self.assertEqual(_page_section(page, "Продолжение измерений", sections, 1), 1)

    def test_header_overflow_is_cropped_without_matching_body_text(self):
        class TextPage:
            def get_text_range(self):
                return "Header\nHeader\nFooter"

            def count_rects(self, start, count):
                self.start = start
                return 1

            def get_rect(self, index):
                return {0: (10, 802, 100, 814), 7: (10, 700, 100, 712),
                        14: (10, 14, 100, 26)}[self.start]

            def close(self):
                pass

        page = SimpleNamespace(get_height=lambda: 842, get_textpage=TextPage)
        section = _Section(595, 842, 30, 20, header_texts=("header",), footer_texts=("footer",))
        self.assertEqual(_protocol_crop(page, section), (0, 34, 0, 48))

def _appendix_starts(texts: list[str], headings: dict[int, tuple[int, str]]) -> dict[int, int]:
    starts = {}
    for index, text in enumerate(texts):
        candidates = []
        for line in text.splitlines():
            heading = _heading(line)
            if heading is None or heading[0] not in headings:
                continue
            number, title = heading
            expected_title = headings[number][1]
            # Заголовок может переноситься в PDF на несколько строк.
            if title and (not expected_title or not expected_title.startswith(title)):
                continue
            candidates.append(number)
        # На странице оглавления перечислены приложения, но нет самих протоколов.
        if len(set(candidates)) > 2:
            continue
        for number in candidates:
            # Даже перенесённая на отдельную строку запись оглавления находится
            # раньше настоящего приложения. «Продолжение» отфильтровано выше.
            starts[number] = index
    return starts
