    footer_texts: tuple[str, ...] = ()


def _compact(text: str) -> str:
    return re.sub(r"\s+", "", unicodedata.normalize("NFKC", text)).casefold()


def _text_key(text: str) -> str:
    return re.sub(r"[^\w]", "", _compact(text)).replace("ё", "е")


def _heading(text: str) -> tuple[int, str] | None:
    match = _HEADING.match(_compact(text))
    if not match:
        return None
    number, tail = int(match[1]), match[2]
    if not 1 <= number <= 99 or "продолжени" in tail:
        return None
    # Оглавление: лидеры и номер страницы не являются заголовком приложения.
    if "..." in tail or "…" in tail or re.search(r"\d[.)]?$", tail):
