        "Для заключения ЭПБ нужен LibreOffice Writer. Установите его и добавьте soffice в PATH "
        "или задайте LIBREOFFICE_PATH — полный путь к исполняемому файлу."
    )


def _convert(source: bytes, directory: Path) -> Path:
    document = directory / "source.docx"
    document.write_bytes(source)
    command = [
        _libreoffice(),
        "-env:UserInstallation=" + (directory / "lo-profile").as_uri(),
        "--headless", "--nologo", "--nodefault", "--nofirststartwizard", "--norestore",
        "--convert-to", "pdf:writer_pdf_Export", "--outdir", str(directory), str(document),
    ]
    try:
        result = subprocess.run(
            command, capture_output=True, timeout=300, check=False,
            env={**os.environ, "SAL_USE_VCLPLUGIN": "svp"},
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("LibreOffice не завершил преобразование ТО в PDF за 5 минут.") from exc
    except OSError as exc:
        raise RuntimeError(f"Не удалось запустить LibreOffice: {exc}") from exc
    pdf = directory / "source.pdf"
    if result.returncode or not pdf.is_file() or not pdf.stat().st_size:
        details = (result.stderr or result.stdout).decode("utf-8", errors="replace").strip()[-1500:]
        raise RuntimeError("LibreOffice не создал PDF технического отчёта." + (" " + details if details else ""))
