    for name in ("soffice", "libreoffice", "soffice.com", "soffice.exe"):
        executable = shutil.which(name)
        if executable:
            return executable
    raise RuntimeError(
        "Для заключения ЭПБ нужен LibreOffice Writer. Установите его и добавьте soffice в PATH "
        "или задайте LIBREOFFICE_PATH — полный путь к исполняемому файлу."
    )


def _convert(source: bytes, directory: Path) -> Path:
    document = directory / "source.docx"
    document.write_bytes(source)
    command = [
        _libreoffice(),
        "-env:UserInstallation=" + (directory / "lo-profile").as_uri(),
        "--headless", "--nologo", "--nodefault", "--nofirststartwizard", "--norestore",
        "--convert-to", "pdf:writer_pdf_Export", "--outdir", str(directory), str(document),
    ]
    try:
        result = subprocess.run(
            command, capture_output=True, timeout=300, check=False,
            env={**os.environ, "SAL_USE_VCLPLUGIN": "svp"},
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("LibreOffice не завершил преобразование ТО в PDF за 5 минут.") from exc
    except OSError as exc:
        raise RuntimeError(f"Не удалось запустить LibreOffice: {exc}") from exc
    pdf = directory / "source.pdf"
    if result.returncode or not pdf.is_file() or not pdf.stat().st_size:
        details = (result.stderr or result.stdout).decode("utf-8", errors="replace").strip()[-1500:]
        raise RuntimeError("LibreOffice не создал PDF технического отчёта." + (" " + details if details else ""))
    return pdf


def _page_texts(document) -> list[str]:
    texts = []
    for index in range(len(document)):
        with closing(document[index]) as page, closing(page.get_textpage()) as textpage:
            texts.append(textpage.get_text_bounded())
    return texts


def _appendix_starts(texts: list[str], headings: dict[int, tuple[int, str]]) -> dict[int, int]:
    starts = {}
    for index, text in enumerate(texts):
        candidates = []
        for line in text.splitlines():
            heading = _heading(line)
            if heading is None or heading[0] not in headings:
                continue
            number, title = heading
            expected_title = headings[number][1]
            # Заголовок может переноситься в PDF на несколько строк.
            if title and (not expected_title or not expected_title.startswith(title)):
                continue
            candidates.append(number)
        # На странице оглавления перечислены приложения, но нет самих протоколов.
        if len(set(candidates)) > 2:
            continue
        for number in candidates:
            # Даже перенесённая на отдельную строку запись оглавления находится
            # раньше настоящего приложения. «Продолжение» отфильтровано выше.
            starts[number] = index
    return starts


def _page_section(page, text: str, sections: list[_Section], fallback: int) -> int:
    width, height = page.get_size()
    compatible = [index for index, section in enumerate(sections)
                  if abs(section.width - width) < 3 and abs(section.height - height) < 3]
    if not compatible:
        raise RuntimeError("Размер страницы PDF не соответствует ни одной секции исходного DOCX.")
    key = _text_key(text)
    scores = {index: sum(len(anchor) for anchor in sections[index].anchors if anchor in key)
              for index in compatible}
    best = max(compatible, key=lambda index: scores[index])
    return best if scores[best] else (fallback if fallback in compatible else compatible[0])


def _png(page, crop=(0, 0, 0, 0)) -> bytes:
    with closing(page.render(scale=_SCALE, crop=crop)) as bitmap:
        with bitmap.to_pil() as image, io.BytesIO() as output:
            image.save(output, format="PNG")
            return output.getvalue()


def _protocol_crop(page, section):
    # Таблица колонтитула может выходить за pgMar: поля секции сами по себе
    # оставляют её нижнюю строку на картинке. Уточняем границу по тексту PDF.
    top, bottom = section.top, section.bottom
    with closing(page.get_textpage()) as textpage:
        raw = textpage.get_text_range()
        key, offsets = [], []
        for index, char in enumerate(raw):
            normalized = _text_key(char)
            key.extend(normalized)
            offsets.extend([index] * len(normalized))
        key = "".join(key)
        for is_header, anchors in ((True, section.header_texts), (False, section.footer_texts)):
            for anchor in anchors:
                start = key.find(anchor)
                while start >= 0:
                    first, last = offsets[start], offsets[start + len(anchor) - 1]
                    count = textpage.count_rects(first, last - first + 1)
                    rects = [textpage.get_rect(i) for i in range(count)]
                    if rects:
                        low, high = min(r[1] for r in rects), max(r[3] for r in rects)
                        if is_header and low >= page.get_height() - section.top - 14:
                            top = max(top, page.get_height() - low + 8)
                        elif not is_header and high <= section.bottom + 14:
                            bottom = max(bottom, high + 8)
                    start = key.find(anchor, start + 1)
    return 0, bottom, 0, top


def render_attachments(source: bytes, *, require_act: bool = True) -> RenderedAttachments:
    """Из готового ТО: приложение 21 целиком, приложения 5–14 без колонтитулов.

    Отсутствующие в ТО необязательные приложения пропускаются. Без протоколов
    результат не собирается. require_act=False допускает отдельный акт вместо
    отсутствующего приложения 21 (act=[]). pages — число страниц всего ТО.
    """
    sections, headings = _document_layout(source)
    if require_act and _ACT_APPENDIX not in headings:
        raise RuntimeError(_MISSING_ACT)
    try:
        with TemporaryDirectory(prefix="expertise-") as temporary:
            path = _convert(source, Path(temporary).resolve())
            # Общий с чтением паспортов lock: PDFium не потокобезопасен.
            with _PDF_LOCK, pdfium.PdfDocument(path) as document:
                texts = _page_texts(document)
                starts = _appendix_starts(texts, headings)
                if require_act and _ACT_APPENDIX not in starts:
                    raise RuntimeError(_MISSING_ACT)
                protocols = sorted(number for number in headings if 5 <= number <= 14)
                if not protocols:
                    raise RuntimeError("В техническом отчёте не найдены протоколы приложений 5–14.")
                missing = [number for number in protocols if number not in starts]
                if missing:
                    raise RuntimeError("В PDF не найдены заголовки приложений ТО: " + ", ".join(map(str, missing)) + ".")
                result: RenderedAttachments = {"act": [], "protocols": [], "pages": len(document)}
                rendered_protocols: set[int] = set()
                for number in [*protocols, *([_ACT_APPENDIX] if _ACT_APPENDIX in starts else [])]:
                    start = starts[number]
                    following = min((other for other in headings if other > number), default=None)
                    if following is not None and following not in starts:
                        raise RuntimeError(f"В PDF не найдена граница приложения {number}: заголовок приложения {following}.")
                    stop = starts[following] if following is not None else len(document)
                    if stop < start:
                        raise RuntimeError("В PDF нарушен порядок заголовков приложений ТО.")
                    if stop == start:
                        if number < 15 and following not in protocols:
                            raise RuntimeError("Протокол и следующее приложение размещены на одной странице; их нельзя разделить по страницам PDF.")
                        stop = start + 1
                    active_section = headings[number][0]
                    for index in range(start, stop):
                        if number != _ACT_APPENDIX and index in rendered_protocols:
                            continue
                        with closing(document[index]) as page:
                            if number == _ACT_APPENDIX:
                                result["act"].append(_png(page))
                                continue
                            active_section = _page_section(page, texts[index], sections, active_section)
                            section = sections[active_section]
                            if section.top + section.bottom >= page.get_height():
                                raise RuntimeError("Поля секции ТО перекрывают всю страницу протокола.")
                            result["protocols"].append(_png(page, _protocol_crop(page, section)))
                            rendered_protocols.add(index)
                return result
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"Не удалось подготовить изображения приложений ТО: {exc}") from exc


def render_act(source: bytes) -> list[bytes]:
    """Отдельный акт DOCX: все страницы без обрезки, в исходном порядке."""
    try:
        with TemporaryDirectory(prefix="expertise-act-") as temporary:
            path = _convert(source, Path(temporary).resolve())
            with _PDF_LOCK, pdfium.PdfDocument(path) as document:
                images = []
                for index in range(len(document)):
                    with closing(document[index]) as page:
                        images.append(_png(page))
                if not images:
                    raise RuntimeError("PDF отдельного акта не содержит страниц.")
                return images
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"Не удалось подготовить изображения отдельного акта: {exc}") from exc

