    def run_selection(self, headings, starts, require_act=True):
        from contextlib import ExitStack
        from unittest.mock import patch
        from app.services.expertise_render import render_attachments

        class Page:
            def __init__(self, index):
                self.index = index
            def get_height(self):
                return 842
            def close(self):
                pass

