                  and _text(p) == '1 Наименование объекта экспертизы'
                  and any('{{full_object_nom}}' in _text(n) for n in children[i + 1:i + 3])), None)
    if first is None:
        raise ValueError('В шаблоне не найден первый раздел.')
    fi = children.index(first)
