                and any('TOC ' in (n.text or '') for n in p.iter(qn('w:instrText')))), None)
    if toc is None or not list(toc.iter(qn('w:hyperlink'))):
        for node in children[ci + 1:fi]:
            if node.tag == qn('w:p'):
                body.remove(node)
        p = OxmlElement('w:p')
        pr = OxmlElement('w:pPr'); pstyle = OxmlElement('w:pStyle')
        pstyle.set(qn('w:val'), styles['toc 1'].style_id); pr.append(pstyle); p.append(pr)
        def add(parent, kind, value=None):
