        add(link, 'text', '1 Наименование объекта экспертизы'); add(link, 'tab')
        add(link, 'begin'); add(link, 'instruction', ' PAGEREF _ExpertiseSeed \\h ')
        add(link, 'separate'); add(link, 'text', '1'); add(link, 'end')
        p.append(link)
