    cp = Paragraph(contents, doc._body)
    cp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cp.paragraph_format.page_break_before = True
    Paragraph(first, doc._body).paragraph_format.page_break_before = True
    for run in cp.runs:
        run.font.name = 'Times New Roman'; run.font.size = Pt(12); run.font.bold = False
    for node in list(body)[:list(body).index(contents)]:
